def decide(policy, strict: bool, connector, zone, credential_kind, user_id=None):
    if zone not in ('company', 'team', 'personal'):
        return Decision(False, 'unknown_zone')
    if zone == 'personal':
        # the pin: personal data is read only with the owner's own grant
        if credential_kind != 'user_grant' or not user_id:
            return Decision(False, 'personal_requires_user_grant')
    if strict:
        mode = 'user_grant'                              # strict mode forces user grants for all zones
    else:
        mode = policy.get((connector, zone))             # missing row means deny
        if mode is None:
            return Decision(False, 'no_policy')
    if mode == 'none':
        return Decision(False, 'disabled')
    allowed = {'app_only': {'app_only'}, 'user_grant': {'user_grant'}, 'both': {'app_only', 'user_grant'}}[mode]
    if credential_kind not in allowed:
        return Decision(False, f'mode_{mode}_forbids_{credential_kind}')
    if credential_kind == 'user_grant' and not user_id:
        return Decision(False, 'user_grant_needs_user')
    return Decision(True, f'mode_{mode}')

DEFAULTS = {'company': 'app_only', 'team': 'app_only', 'personal': 'user_grant'}   # seeded per connector, then editable

def seed_defaults(policy_rows, connector):
    return [(connector, z, m) for z, m in DEFAULTS.items() if (connector, z) not in policy_rows]

