import httpx

EXCHANGE_GRANT = 'urn:ietf:params:oauth:grant-type:token-exchange'   # RFC 8693

def link_app(db, vault, manifest, user, app):
    if not user.session_valid:
        return LinkResult('needs_sso', None)
    m = manifest[app]
    if m.get('federates'):                                   # apps that accept the company identity
        r = httpx.post(m['token_endpoint'], data={
            'grant_type': EXCHANGE_GRANT,
            'subject_token': user.sso_access_token,
            'subject_token_type': 'urn:ietf:params:oauth:token-type:access_token',
            'resource': m['brain_resource'],                  # RFC 8707 audience
        }, timeout=5)
        if r.status_code == 200:
            tok = r.json()
            vault.put(user.tenant, user.id, app, tok['refresh_token'], tok.get('scope'))   # encrypted under the user's key
            set_state(db, user, app, 'linked', 'exchange')
            return LinkResult('linked', None)
        # exchange refused: fall through to consent, once per 10 minutes
        if recently_tried(db, user, app, minutes=10):
            set_state(db, user, app, 'failed', None)
            return LinkResult('failed', None)
    url = consent_url(m, state=bind_state(user.id, app))     # tricky part: state bound to the verified user
    set_state(db, user, app, 'needs_consent', 'consent')
    return LinkResult('needs_consent', url)

def refresh(db, vault, user, app, attempt):
    delays = [60, 300, 1800]                                 # 1 min, 5 min, 30 min
    ok = vault.rotate(user.tenant, user.id, app)             # store the new refresh token before dropping the old
    if ok:
        return set_state(db, user, app, 'linked', None)
    if attempt + 1 >= len(delays):
        return set_state(db, user, app, 'expired', None)
    schedule_retry(user, app, delays[attempt])

