RANK = {'company': 0, 'team': 1, 'personal': 2}
CAP = 200

def merge_views(admin, user, principals):
    by_uri, conflicts = {}, 0
    for view, hits in (('admin', admin), ('user', user)):
        for h in hits:
            u = normalise_uri(h.uri)
            cur = by_uri.setdefault(u, {'admin': None, 'user': None})
            prev = cur[view]
            if prev is None or h.score > prev.score:
                cur[view] = h                      # same uri twice in one view: best score
    out = []
    for u, v in by_uri.items():
        a, b = v['admin'], v['user']
        if a and b:
            allow = set(a.allow) & set(b.allow)    # stricter wins: intersection
            if a.allow and not set(a.allow) <= set(b.allow):
                conflicts += 1
            zone = a.zone if RANK[a.zone] >= RANK[b.zone] else b.zone
            score, views = max(a.score, b.score), ['admin', 'user']
        else:
            h = a or b
            allow, zone, score = set(h.allow), h.zone, h.score
            views = ['admin'] if a else ['user']
        if allow & principals:                     # visible only if the asker holds a surviving principal
            out.append(Merged(u, score, zone, sorted(allow), views))
    out.sort(key=lambda m: (-m.best_score, m.uri))
    return out[:CAP], conflicts

