import math, random

MIN_N = 100
Z = 1.96   # 95 percent

def estimate(n: int, missing: int, total: int | None):
    if n < MIN_N:
        return GapEstimate(None, None, None, False)        # not enough data, no percentage
    p = missing / n
    margin = Z * math.sqrt(p * (1 - p) / n)
    gap = round(p * total) if total is not None else None  # some apps give no cheap total: unknown
    return GapEstimate(p, margin, gap, True)

def probe(db, grant, app, tenant, user, n=400):
    if grant.kind != 'user_grant':
        raise PermissionError('probe needs the user own grant')   # never the admin token
    ids = grant.list_ids(app)                                  # ids only, no content
    ids = [i for i in ids if not too_new(i, minutes=15)]       # skip items younger than the sync window
    if not ids:
        return GapEstimate(0.0, 0.0, 0, True)
    sample = ids if len(ids) <= n else random.Random(hash_seed(user)).sample(ids, n)
    held = {r[0] for r in db.execute(
        'SELECT native_id FROM pointer WHERE tenant_id=%s AND source=%s AND native_id = ANY(%s)',
        (tenant, app, sample))}
    missing = sum(1 for i in sample if i not in held)
    est = estimate(len(sample), missing, grant.total_count(app))
    db.execute('INSERT INTO gap_user VALUES (%s,%s,%s,%s,%s,%s,now()) ON CONFLICT (tenant_id,user_id,app) DO UPDATE SET sampled=EXCLUDED.sampled, missing=EXCLUDED.missing, total_estimate=EXCLUDED.total_estimate, at=now()',
               (tenant, user, app, len(sample), missing, est.gap_total))
    return est   # the admin view reads only gap_admin: per app, at least 5 users
